/* Dirección visual de las maquetas. Todas las fotografías de campaña son conceptuales. */
const asset=n=>'/assets/neon/'+n+'.png';
const icon=(name,cls='')=>`<img class="png-icon ${cls}" src="${asset('icon-'+name)}" alt="" aria-hidden="true">`;
const mark=(large=false)=>`<div class="universe-mark ${large?'large-mark':''}" aria-label="27 Miss Universe Arica 2027"><div class="mark-symbol"><img class="mark-number" src="${asset('logo-27')}" alt="27"><img class="mark-star" src="${asset('crystal-star')}" alt=""></div><div class="mark-title">MISS <span>✧</span> UNIVERSE</div><div class="mark-city">A R I C A</div>${large?'<div class="mark-year">2 0 2 7</div>':''}</div>`;
const portalLinks=[['crown','EL CERTAMEN','certamen'],['profile','CANDIDATAS 2027','candidatas'],['heart','VOTACIÓN ONLINE','votacion'],['trophy','RANKING EN VIVO','ranking'],['star','ARCHIVO 2026','archivo'],['gallery','GALERÍA','galeria']];
const portal=(items=portalLinks)=>`<div class="portal-bar">${items.map(([ic,t,r])=>`<a href="#${r}">${icon(ic)}<span>${t}</span><i>↗</i></a>`).join('')}</div>`;
const campaignNotice='<span class="campaign-credit">IMAGEN CONCEPTUAL DE CAMPAÑA · NO ES UNA CANDIDATA REGISTRADA</span>';
const baseHome=home,baseCards=cards,baseProfile=profile,baseRender=render;
home=function(){return `<section class="crystal-hero" id="crystal-scene"><h1 class="visually-hidden">Miss Universo Arica 2027. Una ciudad que inspira, un universo de talentos.</h1><div class="scene-landscape" data-depth="0.018"></div><div class="scene-aura"></div><canvas id="stardust" aria-hidden="true"></canvas><img class="scene-crystal left" src="${asset('crystal-left')}" alt="" data-depth="0.035"><img class="scene-muse" src="${asset('muse-v3')}" alt="Modelo conceptual de la campaña 2027" data-depth="0.012"><img class="scene-crystal right" src="${asset('crystal-left')}" alt="" data-depth="-0.028"><div class="scene-ribbon ribbon-one"></div><div class="scene-ribbon ribbon-two"></div><div class="scene-copy"><div class="vertical-values">BELLEZA<br>CULTURA<br>TURISMO<br>TALENTO<br>JUVENTUD</div>${mark(true)}<div class="campaign-line">UNA CIUDAD QUE INSPIRA<br>UN UNIVERSO DE TALENTOS</div><div class="actions">${btn('CONOCE EL CERTAMEN','certamen',true)}${btn('POSTULA 2027','casting')}</div></div><div class="scene-coordinate">18°28′ S &nbsp; 70°18′ O <span>ARICA · CHILE</span></div><button class="motion-toggle" aria-pressed="false" title="Pausar o activar efectos">◌ <span>Pausar efectos</span></button>${campaignNotice}<div class="hero-portals">${portal()}</div><a class="scroll-cue" href="#universo">EXPLORA EL UNIVERSO <span>↓</span></a></section><section class="neon-section" id="universo-home"><div class="neon-triple"><a class="image-card certamen-card" href="#certamen"><img src="${asset('muse-v3')}" alt="Imagen conceptual de campaña" loading="lazy"><div><span class="mini-label">MUCHO MÁS QUE BELLEZA</span><h2>EL CERTAMEN</h2><p>Identidad, propósito y una nueva mirada desde el norte.</p><span class="neon-pill">CONOCE MÁS →</span></div></a><a class="image-card arica-card" href="#arica"><div><span class="mini-label">UNA CIUDAD ÚNICA</span><h2>ARICA</h2><p>El mar. El desierto. Una luz que no se parece a ninguna.</p><span class="neon-pill">DESCUBRE ARICA →</span></div></a><a class="image-card crown-card" href="#camino"><img src="${asset('crown-crystal')}" alt="Corona conceptual de cristal" loading="lazy"><div><span class="mini-label">17 NIVELES · UN PROPÓSITO</span><h2>CAMINO A<br>LA CORONA</h2><span class="neon-pill">COMIENZA EL VIAJE →</span></div></a></div></section><section class="neon-section candidate-home"><div class="section-head"><div><div class="eyebrow">BELLEZA · TALENTO · PROPÓSITO</div><h2>CANDIDATAS 2027</h2></div><a class="neon-pill" href="#candidatas">VER TODAS →</a></div>${cards()}</section><section class="neon-section"><div class="gala-banner"><img src="${asset('gala-crystal')}" alt="Escenario conceptual de gala con arquitectura de cristal" loading="lazy"><div><div class="eyebrow">TU VOZ IMPULSA SU HISTORIA</div><h2>EL ESCENARIO ES ARICA.<br>EL FUTURO NO TIENE LÍMITES.</h2><p>Descubre las misiones, acompaña a las candidatas y sé parte de este universo.</p><div class="actions">${btn('VOTA POR TU FAVORITA','votacion',true)}${btn('MISIONES Y DESAFÍOS','misiones')}</div></div></div></section><section class="neon-section"><div class="section-head"><div><div class="eyebrow">CADA PASO CUENTA</div><h2>17 NIVELES. UNA TRANSFORMACIÓN.</h2></div><a class="neon-pill" href="#camino">EXPLORAR EL CAMINO →</a></div><div class="level-preview">${levels.map((l,i)=>`<a href="#camino" style="--i:${i}"><span>${i+1}</span><small>${esc(l)}</small></a>`).join('')}</div></section><section class="neon-section"><div class="section-head"><div><div class="eyebrow">LO QUE NOS CONECTA</div><h2>UN UNIVERSO PARA DESCUBRIR.</h2></div></div><div class="explore-grid">${[['gallery','GALERÍA','galeria','gala-crystal'],['news','NOTICIAS','noticias','arica-panorama'],['calendar','EVENTOS','eventos','gala-crystal'],['star','HISTORIA 2026','archivo','crown-crystal']].map(([ic,t,r,img])=>`<a class="explore-tile" href="#${r}" style="--tile-image:url('${asset(img)}')">${icon(ic)}<span>${t}</span><b>→</b></a>`).join('')}</div></section><section class="neon-section"><div class="section-head"><div><div class="eyebrow">MARCAS QUE CREEN EN EL TALENTO</div><h2>NUESTROS SPONSORS</h2></div>${btn('QUEREMOS SER SPONSOR','sponsors',true)}</div>${state.sponsors.length?`<div class="sponsor-wall">${state.sponsors.map(s=>`<article><h3>${esc(s.name)}</h3><p>${esc(s.description)}</p></article>`).join('')}</div>`:empty('El próximo gran vínculo comienza aquí','Espacios reservados para marcas confirmadas. Conversemos sobre cómo tu marca puede acompañar este camino.',btn('CONSTRUYAMOS UNA ALIANZA','sponsors'))}</section><section class="neon-section"><div class="section-head"><div><div class="eyebrow">NOTICIAS Y EVENTOS</div><h2>EL NORTE TIENE ALGO QUE CONTAR.</h2></div><a class="neon-pill" href="#noticias">VER NOVEDADES →</a></div>${newsCards()}</section><section class="neon-section"><div class="casting-banner"><img src="${asset('crystal-star')}" alt="" loading="lazy"><div><div class="eyebrow">TU HISTORIA MERECE UN ESCENARIO</div><h2>SUEÑA. INSPIRA. CONQUISTA.</h2><p>Manifiesta tu interés en el casting de Arica 2027.</p></div>${btn('POSTULA 2027','casting',true)}</div></section>`};
cards=function(){if(state.candidates.length)return `<div class="neon-candidates">${state.candidates.map((c,i)=>`<a href="#perfil/${encodeURIComponent(c.id)}" class="neon-candidate candidate">${c.photo?`<img src="${esc(c.photo)}" alt="${esc(c.name)}" loading="lazy">`:`<div class="portrait-unavailable">${icon('profile')}</div>`}<div><small>CANDIDATA ${String(i+1).padStart(2,'0')}</small><h3>${esc(c.name)}</h3><span>VER PERFIL →</span></div><b class="candidate-level">${icon('crown')} ${c.level||1}</b></a>`).join('')}</div>`;return `<div class="candidate-reserved"><div class="reserved-art"><img src="${asset('crown-crystal')}" alt="Corona conceptual" loading="lazy"><div class="orbit orbit-a"></div><div class="orbit orbit-b"></div></div><div><span class="mini-label">EL SIGUIENTE CAPÍTULO ESTÁ POR COMENZAR</span><h3>AQUÍ BRILLARÁN<br>LAS PROTAGONISTAS.</h3><p>Las fichas, fotografías y redes se publicarán al confirmar las candidatas. Tu historia puede ser parte de esta edición.</p>${btn('QUIERO SER PARTE','casting',true)}</div><div class="reserved-slots" aria-hidden="true">${[1,2,3].map(n=>`<div>${icon('profile')}<span>ARICA 2027</span><small>PRÓXIMAMENTE</small></div>`).join('')}</div></div>`};
profile=function(id){const c=state.candidates.find(x=>x.id===id);if(!c)return baseProfile(id);return `<section class="profile-scene"><div class="profile-backdrop"></div>${c.photo?`<img class="profile-portrait" src="${esc(c.photo)}" alt="${esc(c.name)}">`:''}<div class="profile-name"><img src="${asset('crown-crystal')}" alt="" class="mini-crown"><div class="eyebrow">CANDIDATA · ARICA 2027</div><h1>${esc(c.name)}</h1><p>MISS UNIVERSO ARICA 2027</p><div class="profile-statbar"><span>${icon('pin')}ARICA</span><span>${icon('crown')}NIVEL ${c.level||1} / 17</span><span>${icon('star')}PROPÓSITO</span></div></div><div class="profile-vote glass"><h3>APOYA SU CAMINO</h3>${icon('heart')}<p>Tu voto la acompaña<br>en esta nueva historia.</p><button class="btn primary" data-vote="${esc(c.id)}" ${!state.settings.free_voting?'disabled':''}>VOTAR AHORA →</button><small>${state.settings.free_voting?'Un voto por cuenta y día':'Votación aún no habilitada'}</small></div></section><section class="neon-section profile-body"><div class="profile-tabs">${[['profile','PERFIL','bio'],['gallery','GALERÍA DE FOTOS','fotos'],['video','GALERÍA DE VIDEOS','videos'],['share','REDES SOCIALES','redes'],['mission','MISIONES','misiones'],['crown','CAMINO A LA CORONA','camino']].map(([ic,t,target])=>`<button data-profile-tab="${target}">${icon(ic)}${t}</button>`).join('')}</div><div class="profile-content-grid"><article class="glass bio" id="profile-bio"><h2>SOBRE ${esc(c.name.split(' ')[0].toUpperCase())}</h2><p>${esc(c.bio)}</p><h3>Su propósito</h3><p>${esc(c.purpose)}</p><span class="signature">Sueña · Inspira · Conquista</span></article><article class="glass" id="profile-fotos"><h2>GALERÍA DE FOTOS</h2><div class="gallery">${(c.gallery||[]).map(u=>`<img src="${esc(u)}" alt="Fotografía de ${esc(c.name)}" loading="lazy" data-lightbox>`).join('')}</div>${!(c.gallery||[]).length?empty('Su historia, en imágenes','Galería pendiente de publicación.'):''}</article><article class="glass" id="profile-videos"><h2>GALERÍA DE VIDEOS</h2>${(c.videos||[]).map((u,i)=>`<a class="video-link" href="${esc(u)}" target="_blank" rel="noopener noreferrer">${icon('video')}<span>VIDEO ${String(i+1).padStart(2,'0')}</span><b>▶</b></a>`).join('')||empty('Historias en movimiento','Videos pendientes de publicación.')}</article><article class="glass" id="profile-redes"><h2>SÍGUELA EN SUS REDES</h2><div class="social-links">${(c.socials||[]).map(s=>`<a class="neon-pill" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${icon('share')}${esc(s.label)} ↗</a>`).join('')||'<p>Enlaces pendientes de publicación.</p>'}</div></article><article class="glass" id="profile-misiones"><h2>MISIONES Y DESAFÍOS</h2><p>Conoce las acciones que forman parte de su preparación.</p>${btn('VER MISIONES','misiones',true)}</article><article class="glass" id="profile-camino"><h2>CAMINO A LA CORONA</h2><div class="progress-ring" style="--progress:${((c.level||1)-1)/17*100}%"><span>${c.level||1}<small>DE 17 NIVELES</small></span></div>${btn('EXPLORAR','camino')}</article></div></section>`};
function designProfile(){const old=state.candidates;state.candidates=[...old,{id:'diseno',name:'Nombre de la candidata',bio:'Aquí se publicará la biografía autorizada de la candidata. Esta pantalla muestra el diseño con imágenes conceptuales; no representa una inscripción real.',purpose:'Su causa y su voz tendrán aquí un espacio propio.',photo:asset('portrait-v3'),level:1,gallery:[asset('portrait-v3'),asset('coast-v3'),asset('gala-v3'),asset('arica-panorama'),asset('gala-crystal')],videos:[],socials:[]}];try{return '<div class="design-preview-notice">VISTA DE DISEÑO · PERFIL SIN DATOS REALES · VOTACIÓN DESACTIVADA</div>'+profile('diseno').replace(/data-vote="diseno"/g,'disabled data-preview-vote="true"')}finally{state.candidates=old}}
function certamen(){return pageTop('BELLEZA · CULTURA · TURISMO · TALENTO','EL CERTAMEN','Una nueva propuesta visual para Miss Universo Arica 2027, donde la identidad de la ciudad y el propósito de sus participantes comparten escenario.')+`<section class="neon-section editorial-split"><div class="editorial-model"><img src="${asset('muse-v3')}" alt="Modelo conceptual de campaña">${campaignNotice}</div><div><div class="eyebrow">MUCHO MÁS QUE BELLEZA</div><h2>UNA CIUDAD QUE INSPIRA.<br>UN UNIVERSO DE TALENTOS.</h2><p>Una experiencia para descubrir historias, desarrollar habilidades y conectar con la cultura, el turismo y la comunidad de Arica.</p><div class="values-grid">${[['star','IDENTIDAD'],['heart','PROPÓSITO'],['pin','TURISMO Y CULTURA'],['crown','PROYECCIÓN']].map(([ic,t])=>`<a class="glass" href="#${ic==='pin'?'arica':'camino'}">${icon(ic)}<h3>${t}</h3></a>`).join('')}</div><div class="notice">Las bases, fechas, requisitos y criterios oficiales se publicarán cuando la organización los confirme.</div>${btn('POSTULA 2027','casting',true)}</div></section>`}
function aricaPage(){return `<section class="arica-immersive"><div><div class="eyebrow">18°28′ S · 70°18′ O</div><h1>ARICA</h1><p>BELLEZA NATURAL.<br>TALENTO SIN FRONTERAS.</p><span class="tag">ILUSTRACIÓN CONCEPTUAL DE LA CIUDAD</span></div></section><section class="neon-section"><div class="section-head"><div><div class="eyebrow">EL ORIGEN DE NUESTRA LUZ</div><h2>MAR. DESIERTO. IDENTIDAD.</h2></div></div><div class="grid">${[['EL MORRO','Un símbolo de la ciudad y parte del paisaje que inspira esta propuesta.'],['EL PACÍFICO','El horizonte y la vida costera, presentes en el universo visual del certamen.'],['CULTURA VIVA','Un espacio para publicar historias y experiencias locales verificadas.']].map(([t,p])=>`<article class="glass">${icon('pin')}<h3>${t}</h3><p>${p}</p></article>`).join('')}</div></section>`}
function galleryPage(){const photos=state.candidates.flatMap(c=>(c.gallery||[]).map(url=>({url,name:c.name,category:'candidatas'})));const concepts=[{url:asset('arica-panorama'),name:'Arica · escenario conceptual',category:'arica'},{url:asset('gala-crystal'),name:'Gala · concepto de escenario',category:'conceptos'},{url:asset('crown-crystal'),name:'Corona · asset de campaña',category:'conceptos'},{url:asset('portrait-v3'),name:'Retrato conceptual · no es candidata',category:'conceptos'},{url:asset('coast-v3'),name:'Campaña conceptual · costa de Arica',category:'conceptos'},{url:asset('gala-v3'),name:'Campaña conceptual · gala',category:'conceptos'}];return pageTop('MOMENTOS QUE CUENTAN UNA HISTORIA','GALERÍA MULTIMEDIA','Fotografías publicadas por la organización y arte conceptual de la propuesta, identificado en cada pieza.')+`<section class="neon-section"><div class="tabbar gallery-filters">${['todas','candidatas','arica','conceptos','videos'].map((v,i)=>`<button class="${!i?'active':''}" data-gallery-filter="${v}">${v.toUpperCase()}</button>`).join('')}</div><div class="media-grid">${[...photos,...concepts].map((p,i)=>`<button class="media-tile" data-media-category="${p.category}" data-open-media="${esc(p.url)}"><img src="${esc(p.url)}" alt="${esc(p.name)}" loading="lazy"><span>${esc(p.name)}</span><b>+</b></button>`).join('')}${state.candidates.flatMap(c=>(c.videos||[]).map(u=>`<a class="media-tile media-video" data-media-category="videos" href="${esc(u)}" target="_blank" rel="noopener noreferrer">${icon('video')}<span>Video · ${esc(c.name)}</span></a>`)).join('')}</div><p class="gallery-no-results hidden">No hay material publicado en esta categoría.</p></section>`}
function contactPage(){return pageTop('CONECTEMOS','CONTACTO','Una pregunta, una idea o una nueva alianza. Tu mensaje llega a la bandeja de la organización en esta instalación.')+`<section class="neon-section"><div class="contact-layout"><aside class="glass"><img class="contact-star" src="${asset('crystal-star')}" alt=""><h2>CONSTRUYAMOS<br>ALGO EXTRAORDINARIO.</h2><p>Para propuestas comerciales visita Sponsors; para manifestar interés en participar visita Casting.</p>${btn('SPONSORS','sponsors')}${btn('CASTING','casting')}<p>No hay direcciones ni teléfonos oficiales cargados todavía.</p></aside><form class="glass form" data-form="lead"><input type="hidden" name="kind" value="contact"><label>Tu nombre<input name="name" required maxlength="120" autocomplete="name"></label><label>Correo electrónico<input name="email" type="email" required autocomplete="email"></label><label>Mensaje<textarea name="message" required maxlength="3000"></textarea></label><label><input type="checkbox" name="consent" required> Autorizo el uso de mis datos para responder esta consulta.</label><button class="btn primary">ENVIAR MENSAJE →</button><p class="form-status" role="status"></p></form></div></section>`}
function rewardsPage(){return pageTop('CAMINO A LA CORONA','RECOMPENSAS E INSIGNIAS','Una propuesta de reconocimiento al aprendizaje y la participación. No hay premios comerciales ni beneficios confirmados.')+`<section class="neon-section"><div class="grid">${[['star','VOZ PROPIA','Identidad y expresión'],['pin','EMBAJADORA DE ARICA','Cultura y conexión local'],['heart','IMPACTO SOCIAL','Propósito y comunidad'],['share','CONEXIÓN','Comunicación y redes'],['mission','CONSTANCIA','Avance de misiones'],['crown','CAMINO A LA CORONA','Preparación integral']].map(([ic,t,p])=>`<article class="glass reward-card">${icon(ic)}<h3>${t}</h3><p>${p}</p><span class="tag">PROPUESTA POR APROBAR</span></article>`).join('')}</div></section>`}
render=async function(){const route=location.hash.slice(1)||'inicio';const custom={certamen,'perfil-diseno':designProfile,arica:aricaPage,galeria:galleryPage,contacto:contactPage,recompensas:rewardsPage,universo:home,eventos:()=>pageTop('AGENDA DEL CERTAMEN','EVENTOS','Encuentros, actividades y experiencias de la edición Arica 2027.')+`<section class="neon-section">${empty('El próximo encuentro está por anunciarse','No hay fechas ni eventos confirmados. Las actividades oficiales se publicarán aquí.')}</section>`};if(custom[route]){$('#main').innerHTML=custom[route]();$('nav').classList.remove('open');$('.menu').setAttribute('aria-expanded','false');bind();window.scrollTo(0,0)}else await baseRender();document.body.dataset.route=route;enhance(route)};
function enhance(route){document.querySelectorAll('[data-profile-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-profile-tab]').forEach(x=>x.classList.toggle('active',b===x));$('#profile-'+b.dataset.profileTab)?.scrollIntoView({behavior:reduced()?'instant':'smooth',block:'start'})});document.querySelectorAll('[data-open-media]').forEach(b=>b.onclick=()=>{$('#lightbox img').src=b.dataset.openMedia;$('#lightbox img').alt=b.querySelector('img')?.alt||'Galería';$('#lightbox').showModal()});document.querySelectorAll('[data-gallery-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-gallery-filter]').forEach(x=>x.classList.toggle('active',b===x));let count=0;document.querySelectorAll('[data-media-category]').forEach(t=>{const visible=b.dataset.galleryFilter==='todas'||b.dataset.galleryFilter===t.dataset.mediaCategory;t.hidden=!visible;if(visible)count++});$('.gallery-no-results')?.classList.toggle('hidden',count>0)});if(route==='camino'){document.querySelectorAll('.level').forEach((l,i)=>{l.style.setProperty('--level-index',i);l.insertAdjacentHTML('afterbegin',icon(i===16?'crown':i<6?'star':i<12?'heart':'mission'))});$('#main .notice')?.insertAdjacentHTML('afterend',`<div class="tabbar journey-tabs"><a class="btn" href="#misiones">MIS MISIONES</a><a class="btn" href="#ranking">RANKING</a><a class="btn" href="#recompensas">RECOMPENSAS</a></div>`)}if(['panel','admin'].includes(route)&&state.user){$('#main .section').classList.add('dashboard');$('#main .section').insertAdjacentHTML('afterbegin',`<aside class="dashboard-sidebar"><h3>MI UNIVERSO</h3>${[['grid','Dashboard',route],['profile','Candidatas','candidatas'],['heart','Votaciones','votacion'],['trophy','Ranking','ranking'],['mission','Misiones','misiones'],['star','Recompensas','recompensas'],['news','Noticias','noticias'],['gallery','Galería','galeria'],['sponsor','Sponsors','sponsors'],['mail','Contacto','contacto']].map(([ic,t,r])=>`<a href="#${r}">${icon(ic)}${t}</a>`).join('')}</aside>`)}if(route==='candidatas')$('#candidate-list')?.insertAdjacentHTML('beforeend','<div class="design-profile-link"><a class="neon-pill" href="#perfil-diseno">EXPLORAR EL DISEÑO DE PERFIL →</a></div>');if(route==='casting'||route==='contacto'||route==='sponsors')document.querySelector('form.form')?.classList.add('neon-form');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('revealed');observer.unobserve(e.target)}}),{threshold:.06});document.querySelectorAll('.neon-section,.level,.glass').forEach(el=>{el.classList.add('reveal');observer.observe(el)});document.querySelector('.scroll-cue')?.addEventListener('click',e=>{e.preventDefault();document.querySelector('#universo-home')?.scrollIntoView({behavior:reduced()?'instant':'smooth'})});startScene();}
let stopScene=()=>{};const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;let effectsPaused=reduced();
function startScene(){stopScene();const scene=$('#crystal-scene'),canvas=$('#stardust');if(!scene||!canvas)return;let frame,visible=true;const ctx=canvas.getContext('2d'),stars=Array.from({length:innerWidth<700?32:80},()=>({x:Math.random(),y:Math.random(),r:Math.random()*1.5+.3,s:Math.random()*.0001+.000025,phase:Math.random()*6}));let w,h;function resize(){w=scene.clientWidth;h=scene.clientHeight;const ratio=Math.min(devicePixelRatio||1,2);canvas.width=w*ratio;canvas.height=h*ratio;ctx.setTransform(ratio,0,0,ratio,0,0)}resize();function draw(t){ctx.clearRect(0,0,w,h);if(!effectsPaused&&visible){stars.forEach(p=>{p.y-=p.s;if(p.y<0)p.y=1;const a=.2+.65*(.5+.5*Math.sin(t*.001+p.phase));ctx.fillStyle=`rgba(195,219,255,${a})`;ctx.shadowColor='#80caff';ctx.shadowBlur=9;ctx.beginPath();ctx.arc(p.x*w,p.y*h,p.r,0,7);ctx.fill()})}frame=requestAnimationFrame(draw)}frame=requestAnimationFrame(draw);function move(e){if(effectsPaused||!matchMedia('(pointer:fine)').matches)return;const r=scene.getBoundingClientRect(),x=e.clientX-r.left-r.width/2,y=e.clientY-r.top-r.height/2;scene.querySelectorAll('[data-depth]').forEach(el=>{const d=Number(el.dataset.depth);el.style.translate=`${x*d}px ${y*d}px`})}function leave(){scene.querySelectorAll('[data-depth]').forEach(el=>el.style.translate='0px 0px')}const toggle=$('.motion-toggle');function update(){document.body.classList.toggle('effects-paused',effectsPaused);toggle.setAttribute('aria-pressed',String(effectsPaused));toggle.querySelector('span').textContent=effectsPaused?'Activar efectos':'Pausar efectos'}toggle.onclick=()=>{effectsPaused=!effectsPaused;update();if(effectsPaused)leave()};update();scene.addEventListener('pointermove',move);scene.addEventListener('pointerleave',leave);window.addEventListener('resize',resize);const ob=new IntersectionObserver(e=>visible=e[0].isIntersecting);ob.observe(scene);stopScene=()=>{cancelAnimationFrame(frame);ob.disconnect();scene.removeEventListener('pointermove',move);scene.removeEventListener('pointerleave',leave);window.removeEventListener('resize',resize)}}
document.querySelectorAll('.brand').forEach(el=>el.innerHTML=mark());$('header nav').innerHTML=[['INICIO','inicio'],['EL CERTAMEN','certamen'],['CANDIDATAS','candidatas'],['VOTACIÓN','votacion'],['RANKING','ranking'],['SPONSORS','sponsors'],['NOTICIAS','noticias'],['GALERÍA','galeria'],['CONTACTO','contacto']].map(([t,r])=>`<a href="#${r}">${t}</a>`).join('');$('.announcement').innerHTML='ARICA · BELLEZA · CULTURA · TURISMO · TALENTO <span>UN NUEVO UNIVERSO · 2027</span>';$('footer>div').innerHTML=[['El certamen','certamen'],['Arica','arica'],['Casting 2027','casting'],['Misiones','misiones'],['Galería','galeria'],['Archivo 2026','archivo'],['Contacto','contacto'],['Privacidad','privacidad'],['Administración','admin']].map(([t,r])=>`<a href="#${r}">${t}</a>`).join('');render();
